code='''from collections import defaultdict
def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        color=grid[r][c]
        if color==0 or (r,c) in seen: continue
        st=[(r,c)]; seen.add((r,c)); cells=[]
        while st:
          x,y=st.pop(); cells.append((x,y))
          for q in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
            a,b=q
            if 0<=a<h and 0<=b<w and grid[a][b]==color and q not in seen: seen.add(q);st.append(q)
        comps.append((color,cells))
    def sig(cells):
      mr=min(x for x,y in cells); mc=min(y for x,y in cells)
      return frozenset((x-mr,y-mc) for x,y in cells)
    examples={}
    for color,cells in comps:
      if color!=1: examples[sig(cells)]=color
    out=[row[:] for row in grid]
    for color,cells in comps:
      if color==1 and sig(cells) in examples:
        for x,y in cells: out[x][y]=examples[sig(cells)]
    return out
'''
